// HasContentType applies the HasEdge predicate on the "content_type" edge.
func HasContentType() predicate.FieldInstanceDef {
	return predicate.FieldInstanceDef(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, false, ContentTypeTable, ContentTypeColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasContentTypeWith applies the HasEdge predicate on the "content_type" edge with a given conditions (other predicates).
func HasContentTypeWith(preds ...predicate.ContentTypeDef) predicate.FieldInstanceDef {
	return predicate.FieldInstanceDef(func(s *sql.Selector) {
		step := newContentTypeStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

