// And groups predicates with the AND operator between them.
func And(predicates ...predicate.FieldInstanceDef) predicate.FieldInstanceDef {
	return predicate.FieldInstanceDef(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.FieldInstanceDef) predicate.FieldInstanceDef {
	return predicate.FieldInstanceDef(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.FieldInstanceDef) predicate.FieldInstanceDef {
	return predicate.FieldInstanceDef(sql.NotPredicates(p))
}
